import React from 'react';
import { Link } from 'react-router-dom';
import './ProductCard.css';

const categoryEmojis = {
  Bed: '🛏️',
  Sofa: '🛋️',
  Table: '🪑',
  Fridge: '🧊',
  'Washing Machine': '🌀',
  TV: '📺'
};

const PlaceholderImage = ({ name, subcategory, category }) => {
  const emoji = categoryEmojis[subcategory] || (category === 'Furniture' ? '🪑' : '⚡');
  const bg = category === 'Furniture' ? '#EEF0FF' : '#D1FAE5';
  const color = category === 'Furniture' ? '#6C63FF' : '#065F46';
  return (
    <div style={{
      width: '100%',
      height: '100%',
      background: bg,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '8px'
    }}>
      <span style={{ fontSize: '52px' }}>{emoji}</span>
      <span style={{ fontSize: '12px', fontWeight: 700, color, textAlign: 'center', padding: '0 8px' }}>{name}</span>
    </div>
  );
};

const ProductCard = ({ product }) => {
  const formatPrice = (price) => `₹${price.toLocaleString('en-IN')}`;
  const categoryColor = product.category === 'Furniture' ? 'badge-purple' : 'badge-green';
  const hasImage = product.images?.[0] && !product.images[0].includes('placeholder') && !product.images[0].includes('unsplash');

  return (
    <Link to={`/products/${product._id}`} className="product-card">
      <div className="product-card-img">
        {hasImage ? (
          <img src={product.images[0]} alt={product.name} loading="lazy"
            onError={e => { e.target.style.display = 'none'; e.target.nextSibling.style.display = 'flex'; }}
          />
        ) : null}
        <PlaceholderImage name={product.name} subcategory={product.subcategory} category={product.category} />
        <span className={`badge ${categoryColor} product-category-badge`}>{product.subcategory}</span>
        {product.availableQuantity === 0 && <div className="out-of-stock-overlay">Out of Stock</div>}
      </div>
      <div className="product-card-body">
        <p className="product-brand">{product.brand}</p>
        <h3 className="product-name">{product.name}</h3>
        <div className="product-pricing">
          <div className="rent-price">
            <span className="price-amount">{formatPrice(product.monthlyRent)}</span>
            <span className="price-label">/month</span>
          </div>
          <div className="deposit-info">Deposit: {formatPrice(product.securityDeposit)}</div>
        </div>
        <div className="product-tenure-tags">
          {product.tenureOptions?.slice(0, 3).map((t, i) => (
            <span key={i} className="tenure-tag">{t.label}</span>
          ))}
        </div>
        <div className="product-card-footer">
          <span className={`condition-dot ${product.condition === 'New' ? 'new' : product.condition === 'Like New' ? 'like-new' : 'good'}`}>
            ● {product.condition}
          </span>
          <span className="view-details">View Details →</span>
        </div>
      </div>
    </Link>
  );
};

export default ProductCard;
